#!/usr/bin/env node
// ╔══════════════════════════════════════════════════════════════════════════╗
// ║ check-agent-mirror-sync — block agent edits that desync runtime mirrors  ║
// ╚══════════════════════════════════════════════════════════════════════════╝
//
// Every agent is authored once under .opencode/agents/<name>.md, mirrored to
// .claude/agents/<name>.md and, where present, .codex/agents/<name>.toml so
// each runtime ships the same behavior. Editing one copy without the others
// makes the runtimes silently disagree. This gate takes the changed agent
// files (or --all) and fails when any agent's mirror drifts from its .opencode
// canonical body, so the divergence is caught at commit / PR time instead of
// in production routing.
'use strict';

// ─────────────────────────────────────────────────────────────────────────────
// 1. REQUIRES
// ─────────────────────────────────────────────────────────────────────────────

const fs = require('node:fs');
const path = require('node:path');
const { NOT_CHECKABLE_CODE, verifyMirrorSync } = require('./lib/mirror-sync-verify.cjs');

// ─────────────────────────────────────────────────────────────────────────────
// 2. CONSTANTS
// ─────────────────────────────────────────────────────────────────────────────

// Repo root relative to this file: bin -> .skilled -> root
const REPO_ROOT = path.resolve(__dirname, '..', '..');
const AGENTS_DIR = path.join(REPO_ROOT, '.opencode', 'agents');

// A changed path counts as an agent definition only when it sits directly inside
// the authored agent directory, under either source root, or a Claude or Codex mirror.
const AGENT_PATH_RE = /(?:^|\/)\.(?:opencode|skilled|claude|codex)\/agents\/[^/]+$/;

// Agents that exist only because Claude Code resolves a subagent by exact name and
// lets a user or project file replace its built-in. No other runtime has that
// built-in, so there is no authored canonical for them to drift from. Keep in step
// with the same list in the /doctor agent-roster check and the symlink sync.
const CLAUDE_ONLY_AGENTS = new Set(['Explore']);

// ─────────────────────────────────────────────────────────────────────────────
// 3. HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function agentNameFromPath(filePath) {
  const normalized = String(filePath).replace(/\\/g, '/');
  if (!AGENT_PATH_RE.test(normalized)) {
    return null;
  }
  return path.basename(normalized, path.extname(normalized));
}

function collectAllAgentNames() {
  return fs
    .readdirSync(AGENTS_DIR)
    .filter((file) => file.endsWith('.md'))
    .map((file) => path.basename(file, '.md'));
}

// ─────────────────────────────────────────────────────────────────────────────
