CLAUDE = []
for rid, file, locator, expected, check, precheck in ROWS:
    if file.startswith(".skilled/agents/"):
        CLAUDE.append((f"R-0{22 + len(CLAUDE)}", file.replace(".skilled/agents/", ".claude/agents/"),
                       locator, expected, check, precheck))

ALL = ROWS + CLAUDE

